/**
 * A small search index over the pages of `docs/guide` (title, headings and a one-line summary),
 * generated by `scripts/build-guide-index.mjs` into `src/help/guideIndex.json`. A test fails when
 * the committed file is out of date, so the Help window can search the guide without reading
 * the markdown at run time.
 */

export interface GuideEntry {
  /** Path under `docs/guide`: `settings.md`, or `tr/settings.md` for a translated page. */
  doc: string;
  title: string;
  headings: string[];
  summary: string;
}

const SUMMARY_MAX = 200;

/** Plain text of a markdown line: links, emphasis, code ticks and HTML tags removed. */
export function plainMarkdown(line: string): string {
  return line
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/<[^>]+>/g, "")
    .replace(/[*`]+|(?<!\w)_+|_+(?!\w)/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

/** The entry of one page; the first `#` heading is the title (the file name when there is none). */
export function indexPage(doc: string, markdown: string): GuideEntry {
  let title = "";
  const headings: string[] = [];
  let summary = "";
  let fenced = false;
  for (const raw of markdown.split(/\r?\n/)) {
    const line = raw.trim();
    if (line.startsWith("```") || line.startsWith("~~~")) {
      fenced = !fenced;
      continue;
    }
    if (fenced || line === "") {
      continue;
    }
    const heading = /^(#{1,3})\s+(.*)$/.exec(line);
    if (heading) {
      const text = plainMarkdown(heading[2]);
      if (heading[1] === "#" && title === "") {
        title = text;
      } else if (text !== "") {
        headings.push(text);
      }
      continue;
    }
    // The first plain sentence of the page: not a table, list, quote, rule or HTML block.
    if (summary === "" && title !== "" && !/^([|>*+-]|\d+\.|<|---|:::)/.test(line)) {
      const text = plainMarkdown(line);
      if (text !== "") {
        summary = text.length > SUMMARY_MAX ? `${text.slice(0, SUMMARY_MAX - 1).trimEnd()}…` : text;
      }
    }
  }
  return { doc, title: title || doc.replace(/\.md$/, ""), headings, summary };
}

/** The index of a set of pages, sorted by file name so the generated file is stable. */
export function buildGuideIndex(files: readonly { name: string; text: string }[]): GuideEntry[] {
  return files
    .filter((f) => f.name.endsWith(".md"))
    .map((f) => indexPage(f.name, f.text))
    .sort((a, b) => (a.doc < b.doc ? -1 : a.doc > b.doc ? 1 : 0));
}

/**
 * The pages to search in one language: its translated pages first, then every English page that has
 * no translation yet (so nothing in the guide becomes unsearchable in a language that is half done).
 */
export function guideForLanguage(
  english: readonly GuideEntry[],
  translated: readonly GuideEntry[]
): GuideEntry[] {
  const done = new Set(translated.map((e) => e.doc.slice(e.doc.lastIndexOf("/") + 1)));
  return [...translated, ...english.filter((e) => !done.has(e.doc))];
}

const foldText = (s: string): string =>
  s.toLocaleLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");

export const GUIDE_RESULT_LIMIT = 5;

/**
 * Guide pages that match every word of the query, best first: a word in the title beats one in
 * a heading, which beats one only in the summary. An empty query matches nothing.
 */
export function searchGuide(
  index: readonly GuideEntry[],
  query: string,
  limit: number = GUIDE_RESULT_LIMIT
): GuideEntry[] {
  const words = foldText(query).split(/\s+/).filter(Boolean);
  if (words.length === 0) {
    return [];
  }
  const scored: { entry: GuideEntry; score: number; order: number }[] = [];
  index.forEach((entry, order) => {
    const title = foldText(entry.title);
    const headings = foldText(entry.headings.join(" "));
    const summary = foldText(entry.summary);
    let score = 0;
    for (const w of words) {
      const s = title.includes(w) ? 3 : headings.includes(w) ? 2 : summary.includes(w) ? 1 : 0;
      if (s === 0) {
        return;
      }
      score += s;
    }
    scored.push({ entry, score, order });
  });
  return scored
    .sort((a, b) => b.score - a.score || a.order - b.order)
    .slice(0, Math.max(0, limit))
    .map((s) => s.entry);
}

